const input = $input.first().json || {};
const execution = input.execution || {};
const workflow = input.workflow || {};
const executionId = String(execution.id || '').trim();
const workflowId = String(workflow.id || '').trim();
const workflowName = String(workflow.name || '').trim();
if (!executionId) throw new Error('missing_failed_execution_id');
if (!workflowId && !workflowName) throw new Error('missing_failed_workflow_identity');

const rawKey = workflowName || ('workflow-' + workflowId);
const workflowKey = rawKey
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 120);
if (workflowKey.length < 2) throw new Error('invalid_failed_workflow_key');

const error = execution.error || {};
const errorCode = String(error.name || error.type || 'N8N_WORKFLOW_ERROR').slice(0, 120);
const errorMessage = String(error.message || 'Workflow execution failed').slice(0, 1200);
const eventId = execution.customData?.event_id || null;

return [{json:{
  receipt:{
    workflow_key: workflowKey,
    workflow_version: String(workflowId || 'unknown').slice(0, 80),
    execution_id: executionId,
    status: 'FAILED',
    idempotency_key: ('n8n-error:' + (workflowId || workflowKey) + ':' + executionId).slice(0, 255),
    occurred_at: new Date().toISOString(),
    owner_id: null,
    event_id: eventId,
    error_code: errorCode,
    error_message: errorMessage
  }
}}];

const crypto = require('crypto');
const receipt = $json.receipt;
const secret = String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET || '').trim();
const url = String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL || '').trim();
if (secret.length < 32) throw new Error('automation_command_secret_not_configured');
if (!url) throw new Error('automation_control_url_not_configured');
const body = JSON.stringify(receipt);
const timestamp = String(Math.floor(Date.now()/1000));
const signature = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(timestamp + '.' + body, 'utf8')
  .digest('hex');
return [{json:{
  receipt_url:url,
  receipt_body:body,
  receipt_timestamp:timestamp,
  receipt_signature:signature
}}];

const response = $input.first().json || {};
const statusCode = Number(response.statusCode || 0);
if (statusCode < 200 || statusCode >= 300) {
  throw new Error('automation_control_receipt_failed_http_' + statusCode);
}
const body = response.body || {};
if (body.accepted !== true) {
  throw new Error('automation_control_receipt_not_accepted');
}
return [{json:{recorded:true,workflow_key:body.workflow_key,execution_id:body.execution_id}}];
